import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.Boholvbs.js";const h=JSON.parse('{"title":"xsync-roadmap(7)","description":"Experiments and features planned for xsync’s performance, in the order they unlock each other.","frontmatter":{"title":"xsync-roadmap(7)","description":"Experiments and features planned for xsync’s performance, in the order they unlock each other.","manual":"xsync-roadmap(7)","manualName":"Roadmap","sectionNumber":"7","pageClass":"roadmap-page"},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md"}'),r={name:"roadmap.md"};function i(d,e,l,o,p,m){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="xsync-roadmap-7" tabindex="-1">xsync-roadmap(7) <a class="header-anchor" href="#xsync-roadmap-7" aria-label="Permalink to &quot;xsync-roadmap(7)&quot;">​</a></h1><div class="rm-hero"><span class="rm-eyebrow"><i aria-hidden="true"></i>ROADMAP · REVIEWED 10 OCTOBER 2026</span><p class="rm-headline">Faster where you sync.<br><span>Lighter while it does.</span></p><p class="rm-lede">xsync already matches rsync on real links and leads it with compression. The next stretch makes every transfer cheaper in CPU and memory, wins back the local lead, and then pushes remote throughput only where measurements show it pays.</p><div class="rm-stats" aria-label="Where xsync stands today"><div class="rm-stat"><span>FRESH COPIES</span><strong>1.00–1.28×</strong><p>rsync’s speed over 1 GbE SSH. Parity without <code>-z</code>, where the link is the ceiling.</p></div><div class="rm-stat"><span>CPU</span><strong>1.6–1.9×</strong><p>rsync’s CPU on fresh copies, and up to 8× on no-op and checksum runs.</p></div><div class="rm-stat"><span>PEAK MEMORY</span><strong>6–22×</strong><p>rsync’s on fresh copies. Near 1 GiB on the 914,106-file corpus.</p></div><div class="rm-stat"><span>APFS NO-OP</span><strong>1.8–3.2×</strong><p>slower than rsync on a loaded machine, against 1.9× faster in the earlier baseline.</p></div></div><p class="rm-stats-note">Measured 10 October 2026 between a Raspberry Pi 5 (ext4) and a Ryzen 7950X (ZFS) over 1 GbE, warm caches, three verified runs per tool. APFS figures come from a loaded M1 Max.</p></div><h2 id="timeline" tabindex="-1">TIMELINE <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;TIMELINE {#timeline}&quot;">​</a></h2><p>Each phase makes the next one’s measurements meaningful. Efficiency comes before throughput: a faster transfer that costs four times the CPU is not faster on a Raspberry Pi.</p><ol class="rm-track"><li class="rm-stop rm-stop-done"><span class="rm-stop-when">SHIPPED</span><a href="https://github.com/s4njee/xsyncv4/blob/main/backlog.md" target="_blank" rel="noopener noreferrer"><strong>Daily-driver CLI</strong><span class="rm-stop-text">P0 trust 15/15 · P1 reach 21/22 · P2 progress closed</span></a></li><li class="rm-stop rm-stop-now"><span class="rm-stop-when">NOW</span><a href="#phase-0"><strong>Phase 0 · Baseline</strong><span class="rm-stop-text">6 items</span></a></li><li class="rm-stop"><span class="rm-stop-when">NEXT</span><a href="#phase-1"><strong>Phase 1 · Efficiency</strong><span class="rm-stop-text">7 items</span></a></li><li class="rm-stop"><span class="rm-stop-when">THEN</span><a href="#phase-2"><strong>Phase 2 · Local lead</strong><span class="rm-stop-text">7 items</span></a><a href="#phase-3"><strong>Phase 3 · Remote throughput</strong><span class="rm-stop-text">7 items</span></a></li><li class="rm-stop"><span class="rm-stop-when">LATER</span><a href="#phase-4"><strong>Phase 4 · Scale</strong><span class="rm-stop-text">5 items</span></a><a href="#phase-5"><strong>Phase 5 · Lock in</strong><span class="rm-stop-text">3 items · ongoing</span></a></li></ol><fieldset class="rm-filter"><legend>Show on the timeline</legend><input type="radio" name="rm-filter" id="rm-filter-all" value="all" checked><label for="rm-filter-all">Everything</label><input type="radio" name="rm-filter" id="rm-filter-experiment" value="experiment"><label for="rm-filter-experiment">Experiments</label><input type="radio" name="rm-filter" id="rm-filter-feature" value="feature"><label for="rm-filter-feature">Features</label><input type="radio" name="rm-filter" id="rm-filter-harness" value="harness"><label for="rm-filter-harness">Measurement</label></fieldset><h2 id="phase-0" tabindex="-1">PHASE 0 · BASELINE <a class="header-anchor" href="#phase-0" aria-label="Permalink to &quot;PHASE 0 · BASELINE {#phase-0}&quot;">​</a></h2><div class="rm-phase rm-horizon-now"><div class="rm-phase-meta"><span class="rm-horizon">NOW</span><span>3 experiments · 3 measurements</span></div><p class="rm-goal">Finish a trustworthy before-picture and make knob sweeps cheap enough to run routinely.</p><p class="rm-exit"><span>EXIT</span>Every later change is judged against the completed neo ↔ freya matrix, with cold-cache and quiet-volume evidence.</p><ol class="rm-items"><li class="rm-item rm-experiment" id="item-0-1"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">0.1</span><span class="rm-backlog">F-01</span><span class="rm-status rm-status-active">IN PROGRESS</span></div><h3>Finish the neo ↔ freya matrix</h3><p>Complete the full Congress corpus (914,106 files) fresh, no-op, checksum and 1% update cases in both directions, three verified runs per tool.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Congress and update-1pct medians appear in the published result table.</dd></div></dl></li><li class="rm-item rm-harness" id="item-0-2"><div class="rm-item-head"><span class="rm-kind">MEASUREMENT</span><span class="rm-ref">0.2</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Runtime tuning overrides</h3><p>Every engine constant is fixed at compile time today. A start-up override for block size, queue limits, thread clamp, zstd level and the delta threshold lets a sweep run without rebuilding.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Result JSON records the effective values for each sample.</dd></div></dl></li><li class="rm-item rm-harness" id="item-0-3"><div class="rm-item-head"><span class="rm-kind">MEASUREMENT</span><span class="rm-ref">0.3</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Sweeps from one command</h3><p>Expose thread counts, deletion and cold-cache modes through the paired runner, with a load / memory / ARC snapshot before and after each case.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>A <code>-j</code> sweep and a <code>--delete</code> case run unattended.</dd></div></dl></li><li class="rm-item rm-harness" id="item-0-4"><div class="rm-item-head"><span class="rm-kind">MEASUREMENT</span><span class="rm-ref">0.4</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Time to durable</h3><p>Report the time until data is on disk (<code>syncfs</code>, <code>F_FULLFSYNC</code>) next to the time until exit. The tool that leaves more dirty pages otherwise looks faster.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Both timings appear side by side for write-heavy cases.</dd></div><div><dt>Evidence</dt><dd>rsync exited with ~2.4 GB still dirty; v1 with ~2.6 MB.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-0-5"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">0.5</span><span class="rm-backlog">F-07</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Quiet APFS re-measurement</h3><p>Repeat the 1/2/4/8-thread APFS diagnostic with low load and at least 20% free space, so filesystem defaults are not chosen from a 98%-full volume.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Thread table recorded with load under 2 and the volume under 80% full.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-0-6"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">0.6</span><span class="rm-backlog">F-01</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Cold-cache protocol</h3><p>Evict caches on both hosts and prove it: ZFS ARC residency on freya, page cache on the Pi.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>At least one cold Congress push and pull, with residency evidence attached.</dd></div><div><dt>Evidence</dt><dd>Warm vs cold walks differed 44.6 vs 101.6 s.</dd></div></dl></li></ol></div><h2 id="phase-1" tabindex="-1">PHASE 1 · EFFICIENCY <a class="header-anchor" href="#phase-1" aria-label="Permalink to &quot;PHASE 1 · EFFICIENCY {#phase-1}&quot;">​</a></h2><div class="rm-phase rm-horizon-next"><div class="rm-phase-meta"><span class="rm-horizon">NEXT</span><span>6 features · 1 measurement</span></div><p class="rm-goal">Reach rsync-class CPU and memory without giving up any safety guarantee.</p><p class="rm-exit"><span>EXIT</span>Across the matrix, CPU ≤ 1.5× and peak memory ≤ 4× rsync’s, with wall time no worse than today.</p><ol class="rm-items"><li class="rm-item rm-feature" id="item-1-1"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">1.1</span><span class="rm-backlog">F-07 · F-08</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Per-directory destination handles</h3><p>Keep one no-follow handle per destination directory and make child operations relative to it, instead of re-walking from the destination root for every file. This keeps the symlink-race protection and removes repeated path walks.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>APFS no-op at or below rsync; receiver system time on Congress at least halved.</dd></div><div><dt>Evidence</dt><dd>63% of APFS profile samples sit in repeated <code>openat</code> walks.</dd></div></dl></li><li class="rm-item rm-feature" id="item-1-2"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">1.2</span><span class="rm-backlog">F-08</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Cache name-collision rules</h3><p>Look up case and normalisation rules once per filesystem, on macOS as well as Linux, and run collision checks once per directory.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Directory walks drop out of the top of the APFS profile.</dd></div></dl></li><li class="rm-item rm-feature" id="item-1-3"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">1.3</span><span class="rm-backlog">F-07</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Unserialised file creation</h3><p>Replace the process-wide output lock with per-file state, so creating and publishing files scales with worker threads.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Wall time improves up to at least 8 threads on ext4 and ZFS.</dd></div></dl></li><li class="rm-item rm-feature" id="item-1-4"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">1.4</span><span class="rm-backlog">F-09</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Release finished directories</h3><p>Free directory records once they and their files complete, and bound the local work queue by bytes and files rather than task count.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Receiver memory on Congress under 200 MiB; a 5-million-file tree stays under a stated bound.</dd></div><div><dt>Evidence</dt><dd>Receiver peaked near 1 GiB against rsync’s 89 MiB.</dd></div></dl></li><li class="rm-item rm-feature" id="item-1-5"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">1.5</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Right-sized compression buffers</h3><p>Compress into per-worker scratch space and queue exactly the bytes produced, so compressed frames stop retaining their worst-case buffer.</p><dl class="rm-facts"><div><dt>Done when</dt><dd><code>-z</code> push peak memory under 100 MiB with unchanged wall time.</dd></div><div><dt>Evidence</dt><dd>Compressed pushes peaked at 292–298 MiB.</dd></div></dl></li><li class="rm-item rm-feature" id="item-1-6"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">1.6</span><span class="rm-backlog">F-06</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Leaner Linux scan</h3><p>Use directory entry types and minimal <code>statx</code> masks, and skip per-entry stats where the listing already answers the question.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Congress no-op CPU within 1.5× rsync.</dd></div></dl></li><li class="rm-item rm-harness" id="item-1-7"><div class="rm-item-head"><span class="rm-kind">MEASUREMENT</span><span class="rm-ref">1.7</span><span class="rm-backlog">F-02</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>CPU and memory gates</h3><p>Extend the CI performance gate beyond wall time, so efficiency gains cannot quietly regress.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>The gate fails on an injected leak or busy loop.</dd></div></dl></li></ol></div><h2 id="phase-2" tabindex="-1">PHASE 2 · LOCAL LEAD <a class="header-anchor" href="#phase-2" aria-label="Permalink to &quot;PHASE 2 · LOCAL LEAD {#phase-2}&quot;">​</a></h2><div class="rm-phase rm-horizon-then"><div class="rm-phase-meta"><span class="rm-horizon">THEN</span><span>4 experiments · 3 features</span></div><p class="rm-goal">Restore and widen xsync’s lead on local copies, starting with Linux filesystems that support cloning.</p><p class="rm-exit"><span>EXIT</span>Local fresh, no-op and update cases lead rsync on APFS, XFS/btrfs and ext4, with thread defaults chosen per filesystem.</p><ol class="rm-items"><li class="rm-item rm-feature" id="item-2-1"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">2.1</span><span class="rm-backlog">F-05</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Linux reflinks and copy offload</h3><p>Probe clone support once per source/destination pair by cloning a real source file, then clone per file. Otherwise use kernel copy offload before falling back to read/write.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>XFS/btrfs fresh copy at least 2× rsync; ext4 not slower.</dd></div><div><dt>Evidence</dt><dd>The one-time probe alone gave 2.98× on ext4; a correct probe turned XFS from 1.61× slower to 1.07× faster.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-2-2"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">2.2</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Whole-file local copies</h3><p>Local updates currently run large changed files through delta matching and re-read them for verification. rsync sends whole files locally because the disk is cheaper than the matcher.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>A/B on an edited 2 GiB file decides the default; the remote delta path is unchanged.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-2-3"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">2.3</span><span class="rm-backlog">F-07</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Threads per filesystem</h3><p>Sweep 1–32 threads for fresh, no-op and update on APFS, ext4, ZFS and XFS, then pick defaults from filesystem type, not core count alone.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Default within 5% of the measured optimum on each filesystem.</dd></div><div><dt>Evidence</dt><dd>Optima ranged from 4 to 32; core count was a poor predictor.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-2-4"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">2.4</span><span class="rm-backlog">F-07</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>APFS creation floor</h3><p>With per-directory handles in place, determine whether ~100 µs per created file is the filesystem itself or contention.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Either reach ~4,600 files/s or document the floor with a standalone benchmark.</dd></div><div><dt>Evidence</dt><dd>4,636 files/s at the APFS optimum.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-2-5"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">2.5</span><span class="rm-backlog">F-10</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Bounded subtree clones</h3><p>Clone a small missing subtree in one call, sized from the scan.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Crossover measured; threshold set from it.</dd></div><div><dt>Evidence</dt><dd>Directory clones won only below ~4–7 MB of missing data.</dd></div></dl></li><li class="rm-item rm-feature" id="item-2-6"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">2.6</span><span class="rm-backlog">F-11</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Clones without full archive mode</h3><p>Clone first, then correct mode and ownership, when <code>-rt</code> or <code>-rlt</code> would otherwise fall back to byte copies.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Faster than create-and-write on APFS.</dd></div></dl></li><li class="rm-item rm-feature" id="item-2-7"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">2.7</span><span class="rm-backlog">F-12</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Parallel deletion</h3><p>Remove stale subtrees in parallel during <code>--delete</code>.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>A 96k-entry stale subtree removed at least 3× faster than <code>rm -rf</code>.</dd></div></dl></li></ol></div><h2 id="phase-3" tabindex="-1">PHASE 3 · REMOTE THROUGHPUT <a class="header-anchor" href="#phase-3" aria-label="Permalink to &quot;PHASE 3 · REMOTE THROUGHPUT {#phase-3}&quot;">​</a></h2><div class="rm-phase rm-horizon-then"><div class="rm-phase-meta"><span class="rm-horizon">THEN</span><span>4 experiments · 3 features</span></div><p class="rm-goal">Push past the single-stream ceiling only where it pays, after efficiency makes the gains cheap.</p><p class="rm-exit"><span>EXIT</span>Compressed, checksum and delta transfers lead rsync on 1 GbE without extra CPU, with a measured plan for faster links.</p><ol class="rm-items"><li class="rm-item rm-feature" id="item-3-1"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">3.1</span><span class="rm-backlog">F-04</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Adaptive compression</h3><p>Decide from a 64 KiB sample of the data whether compression saves at least 5%, honour <code>--skip-compress</code>, and measure the link-speed crossover.</p><dl class="rm-facts"><div><dt>Done when</dt><dd><code>-z</code> on incompressible data within 3% of <code>-a</code>; compressible data no worse.</dd></div><div><dt>Evidence</dt><dd>1.66× on congress-100k; incompressible data added 0% to wire bytes.</dd></div></dl></li><li class="rm-item rm-feature" id="item-3-2"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">3.2</span><span class="rm-backlog">F-14</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Pipelined checksums</h3><p>Hash on the transfer pool, overlapping with listing, and hash receiver candidates in parallel.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Large-file <code>-c</code> pull at least matches rsync.</dd></div><div><dt>Evidence</dt><dd>Skipping hashing entirely saved 0 ms once it overlapped.</dd></div></dl></li><li class="rm-item rm-feature" id="item-3-3"><div class="rm-item-head"><span class="rm-kind">FEATURE</span><span class="rm-ref">3.3</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Asynchronous delta requests</h3><p>Keep several basis signatures in flight instead of blocking a worker on a round trip per file.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Remote update of 100 edited 8 MiB files at least matches rsync.</dd></div><div><dt>Evidence</dt><dd>Removing per-chunk acks took pushes from 62.9 MB/s to line rate.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-3-4"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">3.4</span><span class="rm-backlog">F-03</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Cipher selection</h3><p>Measure ChaCha20 against AES-GCM on the Pi and the workstation. The current link negotiates ChaCha20 both ways.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Decision recorded with the Pi’s own numbers.</dd></div><div><dt>Evidence</dt><dd>Loopback: 845 MB/s ChaCha20 vs 2,374 MB/s AES-GCM; within 4% at 1 GbE.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-3-5"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">3.5</span><span class="rm-backlog">F-03</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Multiple streams for large files</h3><p>Only if one SSH stream proves to be the ceiling: stripe files of 16 MiB or more across connections, never small-file trees.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>At least 1.4× on a large file over 10 GbE with no small-tree regression.</dd></div><div><dt>Evidence</dt><dd>1.41× at 16 MiB, 1.94× at 64 MiB, 0.90× on small files.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-3-6"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">3.6</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Receiver worker count</h3><p>Compare the receiver capped at eight workers with today’s sixteen, once creation is unserialised.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Default set from the sweep.</dd></div><div><dt>Evidence</dt><dd>Workers 1 → 2 → 8 → 16: 11.45 → 9.23 → 8.75 → 8.80 s.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-3-7"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">3.7</span><span class="rm-backlog">F-13</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Tiny transfers</h3><p>Break down start-up cost (worker pool, handshake round trip) against rsync.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>A single small file within 10 ms of rsync in both directions.</dd></div></dl></li></ol></div><h2 id="phase-4" tabindex="-1">PHASE 4 · SCALE <a class="header-anchor" href="#phase-4" aria-label="Permalink to &quot;PHASE 4 · SCALE {#phase-4}&quot;">​</a></h2><div class="rm-phase rm-horizon-later"><div class="rm-phase-meta"><span class="rm-horizon">LATER</span><span>5 experiments</span></div><p class="rm-goal">Hold the lead on the trees, links and hardware you actually use.</p><p class="rm-exit"><span>EXIT</span>No superlinear cost in tree size, depth or width, and documented behaviour on slow links and the Pi.</p><ol class="rm-items"><li class="rm-item rm-experiment" id="item-4-1"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">4.1</span><span class="rm-backlog">F-09</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Millions of files</h3><p>A 5-million-file synthetic tree and a 1-million-file real tree, measured for memory and wall time.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Stated memory bound met; receiver memory flat in tree size.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-4-2"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">4.2</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Pathological shapes</h3><p>One directory of 500k entries, trees 64+ levels deep, and long names.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>No superlinear CPU on APFS, ext4 or ZFS.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-4-3"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">4.3</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Metadata-heavy runs</h3><p>Price hard links, xattrs and ACLs on the Congress corpus.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Each within 1.2× of the plain archive-mode ratio to rsync.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-4-4"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">4.4</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Shaped links</h3><p>No-op, 1% update and delta over emulated 20 ms / 100 Mb/s and 80 ms / 20 Mb/s links.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>High-latency regressions identified and recorded.</dd></div></dl></li><li class="rm-item rm-experiment" id="item-4-5"><div class="rm-item-head"><span class="rm-kind">EXPERIMENT</span><span class="rm-ref">4.5</span><span class="rm-status rm-status-planned">PLANNED</span></div><h3>Pi soak</h3><p>Repeat the Congress push on the Pi, cooled and uncooled, with a sustained soak.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Drift under 5%, or documented.</dd></div><div><dt>Evidence</dt><dd>Pi thermal drift of 18.1 → 27.1 s.</dd></div></dl></li></ol></div><h2 id="phase-5" tabindex="-1">PHASE 5 · LOCK IN <a class="header-anchor" href="#phase-5" aria-label="Permalink to &quot;PHASE 5 · LOCK IN {#phase-5}&quot;">​</a></h2><div class="rm-phase rm-horizon-always"><div class="rm-phase-meta"><span class="rm-horizon">ALWAYS</span><span>3 measurements</span></div><p class="rm-goal">Turn every verified win into a permanent check.</p><p class="rm-exit"><span>EXIT</span>Each phase closes by advancing the pinned CI reference to the improved build.</p><ol class="rm-items"><li class="rm-item rm-harness" id="item-5-1"><div class="rm-item-head"><span class="rm-kind">MEASUREMENT</span><span class="rm-ref">5.1</span><span class="rm-backlog">F-02</span><span class="rm-status rm-status-ongoing">ONGOING</span></div><h3>Advance the reference</h3><p>Move the CI gate’s pinned reference forward after each verified improvement, so later changes protect it.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>The reference never trails a released performance gain.</dd></div></dl></li><li class="rm-item rm-harness" id="item-5-2"><div class="rm-item-head"><span class="rm-kind">MEASUREMENT</span><span class="rm-ref">5.2</span><span class="rm-backlog">F-02</span><span class="rm-status rm-status-ongoing">ONGOING</span></div><h3>New CI scenarios</h3><p>Add incompressible <code>-z</code> (memory), deep-tree no-op (walk cost), large <code>--delete</code> and large-file <code>-c</code> fixtures.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>Each confirmed fix has a scenario that would catch its regression.</dd></div></dl></li><li class="rm-item rm-harness" id="item-5-3"><div class="rm-item-head"><span class="rm-kind">MEASUREMENT</span><span class="rm-ref">5.3</span><span class="rm-status rm-status-ongoing">ONGOING</span></div><h3>Generated results</h3><p>Generate the README benchmark table from verified results, keeping historical numbers clearly labelled.</p><dl class="rm-facts"><div><dt>Done when</dt><dd>No hand-edited performance numbers.</dd></div></dl></li></ol></div><h2 id="lessons" tabindex="-1">LESSONS FROM XSYNC V1 <a class="header-anchor" href="#lessons" aria-label="Permalink to &quot;LESSONS FROM XSYNC V1 {#lessons}&quot;">​</a></h2><p>xsync v1, an earlier Rust implementation, ran a long tuning programme across APFS, ext4, XFS, ZFS, Windows and a Raspberry Pi. Its winners shape the plan above; its losers are parked until new evidence contradicts them.</p><div class="rm-lessons"><div class="rm-lesson"><span>WHAT WON</span><ul><li><strong>One-time reflink probe</strong><em>2.98× on ext4</em></li><li><strong>Native whole-directory clones</strong><em>6.3× over per-file clones</em></li><li><strong>Small-file batching and pipelining</strong><em>25.5× over SSH</em></li><li><strong>Sampled adaptive compression</strong><em>1.66× on congress-100k</em></li><li><strong>No per-chunk acknowledgements</strong><em>62.9 MB/s → line rate</em></li><li><strong>Striping large files only</strong><em>1.41–1.94× at 16–64 MiB</em></li></ul></div><div class="rm-lesson"><span>PARKED</span><ul><li><strong>io_uring create/write path</strong><em>4% ceiling</em></li><li><strong>Dedicated writer threads, fsync tuning</strong><em>flat</em></li><li><strong>Hash caching, cheaper hashes</strong><em>within noise</em></li><li><strong>Extra connections for small-file trees</strong><em>0.90×</em></li><li><strong>zstd level 1 or 9</strong><em>5% faster / 2× slower</em></li><li><strong>Persistent destination index</strong><em>1.09 GB at 1M files</em></li></ul></div></div><h2 id="method" tabindex="-1">HOW WE MEASURE <a class="header-anchor" href="#method" aria-label="Permalink to &quot;HOW WE MEASURE {#method}&quot;">​</a></h2><p>Environment changes impersonated code changes three times in v1. Every experiment on this page follows these rules:</p><ol class="rm-method"><li>Run xsync and rsync paired, in rotated order, and judge ratios rather than absolute times.</li><li>Verify every sample independently; a wrong tree fails the run even when the tool exits 0.</li><li>Report wall time, CPU split by endpoint, peak memory and context switches.</li><li>Label the source revision, binary hash, filesystem, free space, load, cache state and cipher.</li><li>Take five or more samples; spread above 15% of the median is inconclusive.</li><li>Decide with a timed A/B on the target, never with a profile alone.</li></ol><h2 id="decisions" tabindex="-1">OPEN DECISIONS <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;OPEN DECISIONS {#decisions}&quot;">​</a></h2><div class="rm-decisions"><div><span>Local delta</span><p>Keep rsync-style whole-file copies for local updates? Recommended, pending experiment 2.2.</p></div><div><span>Thread default</span><p>A per-filesystem table, or one conservative default with documentation?</p></div><div><span>Cipher</span><p>Should xsync ever choose an SSH cipher on the user’s behalf, or only document the choice?</p></div><div><span>Performance budget</span><p>Adopt CPU ≤ 1.5× and memory ≤ 4× rsync as standing CI gates?</p></div></div><h2 id="sources" tabindex="-1">SOURCES <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;SOURCES {#sources}&quot;">​</a></h2><p>Condensed from <code>ROADMAP.md</code> in the <a href="https://github.com/s4njee/xsyncv4" target="_blank" rel="noopener noreferrer">source repository</a>, which cites every figure. It links the verified benchmark results and the xsync v1 tuning records. Planned work here is not part of the command reference; see <a href="development.html">development status</a> for what ships today.</p>',28)])])}const u=s(r,[["render",i]]);export{h as __pageData,u as default};
